function validate(input) {
  const [{ FriendRequest = [], RequestAccepted = [] }] = input;
  const date = /^\d{4}-\d{2}-\d{2}$/;
  for (const [table, rows] of [['FriendRequest', FriendRequest], ['RequestAccepted', RequestAccepted]])
    for (const [a, b, day] of rows) {
      if (a === null || b === null) return `${table} ids must not be null.`;
      if (typeof day !== 'string' || !date.test(day)) return `${table} has a bad date ${day}.`;
    }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const users = small ? 4 : 60;
  const pick = n => 1 + Math.floor(rand() * n);
  const day = () => `2016-06-${String(pick(small ? 10 : 28)).padStart(2, '0')}`;
  const pair = () => { const a = pick(users); let b = pick(users - 1); if (b >= a) b += 1; return [a, b]; };
  const FriendRequest = [], RequestAccepted = [];
  const requests = small ? Math.floor(rand() * 8) : 2000;
  for (let i = 0; i < requests; i++) {
    // Some rows repeat an earlier request exactly or with a later date.
    const [a, b] = FriendRequest.length && rand() < 0.25 ? FriendRequest[Math.floor(rand() * FriendRequest.length)] : pair();
    FriendRequest.push([a, b, day()]);
  }
  const accepts = small ? Math.floor(rand() * 8) : 2000;
  for (let i = 0; i < accepts; i++) {
    // Most acceptances answer a real request; some do not, and some repeat.
    const [a, b] = FriendRequest.length && rand() < 0.7 ? FriendRequest[Math.floor(rand() * FriendRequest.length)] : pair();
    RequestAccepted.push([a, b, day()]);
  }
  return [{ FriendRequest, RequestAccepted }];
}
